"""Tests for summarize.py."""
from summarize import summarize


def test_basic():
    rows = [
        {"region": "EU", "revenue": 100},
        {"region": "US", "revenue": 200},
        {"region": "EU", "revenue": 50},
    ]
    assert summarize(rows) == {"EU": 150.0, "US": 200.0}


def test_numeric_strings():
    rows = [
        {"region": "APAC", "revenue": "30.5"},
        {"region": "APAC", "revenue": "9.5"},
    ]
    assert summarize(rows) == {"APAC": 40.0}


def test_missing_revenue_ignored():
    rows = [
        {"region": "EU", "revenue": None},
        {"region": "US", "revenue": 10},
    ]
    assert summarize(rows) == {"US": 10.0}


def test_unparseable_revenue_ignored():
    rows = [
        {"region": "EU", "revenue": "NaN"},
        {"region": "US", "revenue": 10},
    ]
    assert summarize(rows) == {"US": 10.0}


def test_empty_input():
    assert summarize([]) == {}


def test_missing_region_key_ignored():
    rows = [
        {"revenue": 10},
        {"region": "US", "revenue": 20},
    ]
    assert summarize(rows) == {"US": 20.0}

